RKfill("bs",[{"b":["Bootstrap adalah framework CSS dengan <b>komponen siap pakai</b> (tombol, kartu, navbar, modal) dan sistem grid. Versi 5 tidak lagi membutuhkan jQuery.","Cara cepat: tambahkan CSS di <code>&lt;head&gt;</code> dan bundle JS di akhir <code>&lt;body&gt;</code> dari CDN jsDelivr: <code>bootstrap@5.3.3/dist/css/bootstrap.min.css</code> dan <code>bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js</code>. Bundle sudah berisi Popper untuk dropdown dan tooltip.","Lewat npm: <code>npm install bootstrap</code>, lalu <code>import \"bootstrap/dist/css/bootstrap.min.css\"</code> dan <code>import \"bootstrap\"</code> di file JS utama.","Pratinjau di halaman ini sudah memuat Bootstrap 5.3, jadi kamu cukup menulis HTML."],"html":"<div class=\"container py-4\">\n  <h1 class=\"display-6\">Toko Nusantara</h1>\n  <p class=\"lead\">Kopi, teh, dan camilan pilihan.</p>\n  <button class=\"btn btn-primary\">Belanja sekarang</button>\n</div>","bs":true,"task":{"q":"Ubah tombol menjadi hijau dengan mengganti <code>btn-primary</code> menjadi <code>btn-success</code>.","test":"document.querySelector('.btn').classList.contains('btn-success')","hint":"Ganti nama kelas btn-primary menjadi btn-success."},"pts":["Bootstrap 5 = komponen + grid + utilitas, tanpa jQuery.","CSS di head, bootstrap.bundle.min.js di akhir body."],"q":[["Apa isi bootstrap.bundle.min.js selain JS Bootstrap?",["Popper","jQuery","React"],0,"Popper dibutuhkan dropdown, tooltip, dan popover."],["Apakah Bootstrap 5 memerlukan jQuery?",["Tidak","Ya","Hanya untuk grid"],0,"Sejak v5 Bootstrap memakai JavaScript biasa."]],"so":[{"q":"Tulis kerangka HTML lengkap yang memuat Bootstrap 5.3.3 dari CDN jsDelivr.","h":"link CSS di head, script bundle sebelum &lt;/body>, dan meta viewport.","a":"<!doctype html>\n<html lang=\"id\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Toko</title>\n  <link href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css\" rel=\"stylesheet\">\n</head>\n<body>\n  <h1 class=\"container\">Halo, Bootstrap!</h1>\n  <script src=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js\"></script>\n</body>\n</html>","lang":"html"},{"q":"Buat tiga tombol berdampingan: Simpan (primary), Batal (outline-secondary), Hapus (danger, kecil).","h":"btn btn-primary, btn btn-outline-secondary, btn btn-danger btn-sm.","a":"<div class=\"d-flex gap-2\">\n  <button class=\"btn btn-primary\">Simpan</button>\n  <button class=\"btn btn-outline-secondary\">Batal</button>\n  <button class=\"btn btn-danger btn-sm\">Hapus</button>\n</div>","lang":"html"}]},{"b":["Grid Bootstrap terdiri dari <code>.container</code> → <code>.row</code> → <code>.col</code>. Setiap baris dibagi 12 kolom.","<code>col-4</code> mengambil 4 dari 12 kolom (sepertiga). Tambahkan titik henti: <code>col-12 col-md-6 col-lg-4</code> berarti penuh di ponsel, setengah mulai 768px, sepertiga mulai 992px.","Titik henti Bootstrap: <code>sm</code> 576px, <code>md</code> 768px, <code>lg</code> 992px, <code>xl</code> 1200px, <code>xxl</code> 1400px. Jarak antarkolom diatur dengan <code>g-3</code> (gutter)."],"html":"<div class=\"container py-3\">\n  <div class=\"row g-3\">\n    <div class=\"col-12 col-md-6\"><div class=\"p-3 bg-info-subtle border rounded\">Dart</div></div>\n    <div class=\"col-12 col-md-6\"><div class=\"p-3 bg-info-subtle border rounded\">Kotlin</div></div>\n    <div class=\"col-12 col-md-6\"><div class=\"p-3 bg-info-subtle border rounded\">Flutter</div></div>\n    <div class=\"col-12 col-md-6\"><div class=\"p-3 bg-info-subtle border rounded\">Compose</div></div>\n  </div>\n</div>","bs":true,"task":{"q":"Buat setiap kolom menjadi sepertiga lebar di layar besar: tambahkan <code>col-lg-4</code> pada keempat kolom.","test":"[...document.querySelectorAll('.row > div')].every(d=>d.classList.contains('col-lg-4'))","hint":"Tambahkan col-lg-4 setelah col-md-6 di setiap div kolom."},"pts":["container → row → col.","12 kolom per baris; col-md-6 = setengah mulai md.","Gutter: g-0 sampai g-5."],"q":[["Berapa lebar col-3 dalam baris 12 kolom?",["Seperempat","Sepertiga","Setengah"],0,"3/12 = 1/4."],["Titik henti lg di Bootstrap 5 mulai lebar?",["768px","992px","1200px"],1,"sm 576, md 768, lg 992, xl 1200, xxl 1400."]],"so":[{"q":"Buat tata letak sidebar 3 kolom dan konten 9 kolom mulai md, ditumpuk di ponsel.","h":"row lalu col-md-3 dan col-md-9.","a":"<div class=\"container\">\n  <div class=\"row g-3\">\n    <aside class=\"col-md-3\"><div class=\"p-3 bg-light border\">Menu</div></aside>\n    <main class=\"col-md-9\"><div class=\"p-3 border\">Konten</div></main>\n  </div>\n</div>","lang":"html"},{"q":"Buat satu kolom selebar 6 yang berada di tengah baris.","h":"offset-3 menggeser kolom 3 satuan, atau justify-content-center pada row.","a":"<div class=\"row justify-content-center\">\n  <div class=\"col-6\"><div class=\"p-3 border text-center\">Tengah</div></div>\n</div>","lang":"html"}]},{"b":["Bootstrap juga punya kelas utilitas: jarak <code>m-3</code>, <code>p-2</code>, <code>mt-4</code>, <code>px-5</code> (skala 0–5), tampilan <code>d-flex</code>, <code>d-none d-md-block</code>, perataan <code>justify-content-between</code>, <code>align-items-center</code>, <code>text-center</code>.","Warna tema: <code>primary</code>, <code>secondary</code>, <code>success</code>, <code>danger</code>, <code>warning</code>, <code>info</code>, <code>light</code>, <code>dark</code>. Dipakai sebagai <code>text-danger</code>, <code>bg-warning</code>, <code>border-success</code>.","Tipografi: <code>display-1</code> sampai <code>display-6</code> untuk judul besar, <code>lead</code> untuk paragraf pembuka, <code>fw-bold</code>, <code>fs-5</code>, <code>text-muted</code>/<code>text-body-secondary</code>."],"html":"<div class=\"container py-3\">\n  <div class=\"d-flex justify-content-between align-items-center p-3 bg-light border rounded\">\n    <span class=\"fw-bold\">Pesanan #1024</span>\n    <span id=\"status\" class=\"badge bg-secondary\">Diproses</span>\n  </div>\n  <p class=\"mt-3 text-body-secondary\">Estimasi tiba: 2 hari.</p>\n</div>","bs":true,"task":{"q":"Ubah status menjadi hijau dengan <code>bg-success</code> menggantikan <code>bg-secondary</code>.","test":"document.getElementById('status').classList.contains('bg-success')","hint":"Ganti bg-secondary pada span#status."},"pts":["Jarak: m-/p- + arah + skala 0–5.","d-flex, justify-content-*, align-items-*.","Warna tema: primary, success, danger, warning, info, dll."],"q":[["Kelas mana yang menyembunyikan elemen di ponsel tapi menampilkannya mulai md?",["d-none d-md-block","d-md-none d-block","hide-md"],0,"d-none untuk semua, lalu d-md-block mulai md."]],"so":[{"q":"Buat bilah ringkasan: teks kiri \"Total belanja\", angka kanan tebal berwarna hijau, sejajar vertikal, padding 3, garis tepi, sudut membulat.","h":"d-flex justify-content-between align-items-center p-3 border rounded; fw-bold text-success.","a":"<div class=\"d-flex justify-content-between align-items-center p-3 border rounded\">\n  <span>Total belanja</span>\n  <span class=\"fw-bold text-success fs-5\">Rp66.150</span>\n</div>","lang":"html"},{"q":"Sembunyikan kolom keterangan di ponsel dan tampilkan mulai lg.","h":"d-none d-lg-block.","a":"<p class=\"d-none d-lg-block text-body-secondary\">Keterangan tambahan untuk layar lebar.</p>","lang":"html"}]},{"b":["Tombol: <code>btn btn-primary</code>, versi garis tepi <code>btn-outline-primary</code>, ukuran <code>btn-sm</code>/<code>btn-lg</code>.","Kartu: <code>.card</code> berisi <code>.card-img-top</code>, <code>.card-body</code>, <code>.card-title</code>, <code>.card-text</code>.","Alert untuk pesan: <code>alert alert-warning</code>. Badge untuk label kecil: <code>badge text-bg-danger</code>."],"html":"<div class=\"container py-3\">\n  <div class=\"alert alert-warning\">Stok kopi Gayo tinggal sedikit.</div>\n  <div class=\"card\" style=\"max-width:18rem\">\n    <div class=\"card-body\">\n      <h5 class=\"card-title\">Kopi Gayo <span class=\"badge text-bg-danger\">Baru</span></h5>\n      <p class=\"card-text\">Arabika dari Aceh, 250 gram.</p>\n      <a class=\"btn btn-primary\">Rp 85.000</a>\n    </div>\n  </div>\n</div>","bs":true,"task":{"q":"Tambahkan tombol kedua di dalam kartu dengan kelas <code>btn btn-outline-secondary</code>.","test":"!!document.querySelector('.card .btn.btn-outline-secondary')","hint":"Tulis <a class=\"btn btn-outline-secondary\">Detail</a> setelah tombol pertama."},"pts":["btn + btn-{warna} atau btn-outline-{warna}.","card → card-body → card-title/card-text.","alert alert-{warna}; badge text-bg-{warna}."],"q":[["Kelas apa untuk tombol bergaris tepi merah?",["btn btn-outline-danger","btn btn-danger-outline","btn-border-red"],0,"Pola btn-outline-{warna}."],["Atribut untuk tombol penutup alert?",["data-bs-dismiss=\"alert\"","data-close","onclick=\"hide()\""],0,"Sama polanya dengan modal."]],"so":[{"q":"Buat alert sukses yang bisa ditutup dengan tombol silang.","h":"alert alert-success alert-dismissible fade show + button.btn-close data-bs-dismiss=\"alert\".","a":"<div class=\"alert alert-success alert-dismissible fade show\" role=\"alert\">\n  Pesanan berhasil dibuat.\n  <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\" aria-label=\"Tutup\"></button>\n</div>","lang":"html"},{"q":"Buat tiga kartu produk sama tinggi berdampingan mulai md.","h":"row row-cols-1 row-cols-md-3 g-3 dan card h-100.","a":"<div class=\"row row-cols-1 row-cols-md-3 g-3\">\n  <div class=\"col\"><div class=\"card h-100\"><div class=\"card-body\"><h5 class=\"card-title\">Kopi Gayo</h5><p class=\"card-text\">Rp85.000</p></div></div></div>\n  <div class=\"col\"><div class=\"card h-100\"><div class=\"card-body\"><h5 class=\"card-title\">Kopi Toraja</h5><p class=\"card-text\">Rp90.000</p></div></div></div>\n  <div class=\"col\"><div class=\"card h-100\"><div class=\"card-body\"><h5 class=\"card-title\">Kopi Kintamani</h5><p class=\"card-text\">Rp80.000</p></div></div></div>\n</div>","lang":"html"}]},{"b":["Navbar Bootstrap otomatis berubah menjadi menu hamburger di layar kecil. Kuncinya: <code>navbar-expand-lg</code> (melebar mulai lg), tombol <code>navbar-toggler</code>, dan wadah <code>collapse navbar-collapse</code>.","Tombol pembuka memakai atribut <code>data-bs-toggle=\"collapse\"</code> dan <code>data-bs-target=\"#menu\"</code>. Tidak perlu menulis JavaScript sendiri, bundle Bootstrap yang menanganinya.","Pratinjau ini sempit, jadi kamu akan melihat tombol hamburger. Klik untuk membuka menu."],"html":"<nav class=\"navbar navbar-expand-lg bg-dark\" data-bs-theme=\"dark\">\n  <div class=\"container-fluid\">\n    <a class=\"navbar-brand\" href=\"#\">RuangKode</a>\n    <button class=\"navbar-toggler\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#menu\" aria-controls=\"menu\" aria-expanded=\"false\" aria-label=\"Buka menu\">\n      <span class=\"navbar-toggler-icon\"></span>\n    </button>\n    <div class=\"collapse navbar-collapse\" id=\"menu\">\n      <ul class=\"navbar-nav\">\n        <li class=\"nav-item\"><a class=\"nav-link active\" href=\"#\">Beranda</a></li>\n        <li class=\"nav-item\"><a class=\"nav-link\" href=\"#\">Kursus</a></li>\n      </ul>\n    </div>\n  </div>\n</nav>","bs":true,"task":{"q":"Tambahkan item menu ketiga \"Masuk\" di dalam <code>.navbar-nav</code>.","test":"document.querySelectorAll('.navbar-nav .nav-item').length>=3","hint":"Salin satu <li class=\"nav-item\">...</li> dan ganti teksnya."},"pts":["navbar-expand-{bp} menentukan kapan menu melebar.","data-bs-toggle=\"collapse\" + data-bs-target=\"#id\"."],"q":[["Atribut apa yang menghubungkan tombol ke menu yang dilipat?",["data-bs-target","data-target-menu","href saja"],0,"data-bs-target berisi selector elemen collapse."]],"so":[{"q":"Ubah navbar agar melebar mulai md (bukan lg) dan menu rata kanan.","h":"navbar-expand-md; tambahkan ms-auto pada ul.navbar-nav.","a":"<nav class=\"navbar navbar-expand-md bg-body-tertiary\">\n  <div class=\"container-fluid\">\n    <a class=\"navbar-brand\" href=\"#\">RuangKode</a>\n    <button class=\"navbar-toggler\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#menu\" aria-controls=\"menu\" aria-expanded=\"false\" aria-label=\"Buka menu\"><span class=\"navbar-toggler-icon\"></span></button>\n    <div class=\"collapse navbar-collapse\" id=\"menu\">\n      <ul class=\"navbar-nav ms-auto\">\n        <li class=\"nav-item\"><a class=\"nav-link\" href=\"#\">Beranda</a></li>\n        <li class=\"nav-item\"><a class=\"nav-link\" href=\"#\">Kursus</a></li>\n      </ul>\n    </div>\n  </div>\n</nav>","lang":"html"}]},{"b":["Input memakai <code>form-control</code>, pilihan <code>form-select</code>, kotak centang <code>form-check-input</code>, label <code>form-label</code>.","Validasi bawaan: beri form atribut <code>novalidate</code> dan kelas <code>needs-validation</code>. Saat dikirim, tambahkan kelas <code>was-validated</code> agar Bootstrap menampilkan <code>.invalid-feedback</code> di bawah input yang salah.","Kamu juga bisa menandai satu input secara manual dengan <code>is-invalid</code> atau <code>is-valid</code>."],"html":"<form id=\"daftar\" class=\"container py-3 needs-validation\" novalidate>\n  <div class=\"mb-3\">\n    <label for=\"nama\" class=\"form-label\">Nama</label>\n    <input id=\"nama\" class=\"form-control\" required>\n    <div class=\"invalid-feedback\">Nama wajib diisi.</div>\n  </div>\n  <div class=\"mb-3\">\n    <label for=\"kelas\" class=\"form-label\">Kelas</label>\n    <select id=\"kelas\" class=\"form-select\"><option>Flutter</option><option>Compose</option></select>\n  </div>\n  <button class=\"btn btn-primary\">Daftar</button>\n</form>","js":"const f = document.getElementById('daftar');\nf.addEventListener('submit', e => {\n  e.preventDefault();\n  // tandai form agar Bootstrap menampilkan pesan validasi\n  f.classList.add('was-validated');\n  if (f.checkValidity()) console.log('Terkirim:', f.nama.value);\n});","bs":true,"task":{"q":"Tambahkan input email (<code>type=\"email\"</code>, kelas <code>form-control</code>, <code>required</code>) beserta pesan <code>invalid-feedback</code>.","test":"(e=>!!e&&e.required&&e.classList.contains('form-control')&&!!e.parentElement.querySelector('.invalid-feedback'))(document.querySelector('#daftar input[type=email]'))","hint":"Salin blok div.mb-3 untuk Nama, ganti id, label, dan type menjadi email."},"pts":["form-control, form-select, form-check-input, form-label.","novalidate + was-validated menampilkan invalid-feedback."],"q":[["Kelas apa yang membuat Bootstrap menampilkan pesan validasi untuk seluruh form?",["was-validated","is-validated","validate-all"],0,"was-validated dipasang pada form."],["Kelas untuk menandai satu input tidak valid secara manual?",["is-invalid","invalid","has-error"],0,"is-valid untuk yang benar."]],"so":[{"q":"Buat dua field berdampingan (Nama depan, Nama belakang) mulai md memakai grid di dalam form.","h":"div.row.g-3 lalu col-md-6 untuk setiap field.","a":"<form class=\"row g-3\">\n  <div class=\"col-md-6\"><label class=\"form-label\" for=\"dp\">Nama depan</label><input id=\"dp\" class=\"form-control\"></div>\n  <div class=\"col-md-6\"><label class=\"form-label\" for=\"bl\">Nama belakang</label><input id=\"bl\" class=\"form-control\"></div>\n</form>","lang":"html"},{"q":"Buat kotak centang persetujuan yang wajib dicentang, terpisah dari kotak centang langganan berita.","h":"form-check + form-check-input + form-check-label; required hanya pada persetujuan.","a":"<div class=\"form-check\">\n  <input class=\"form-check-input\" type=\"checkbox\" id=\"setuju\" required>\n  <label class=\"form-check-label\" for=\"setuju\">Saya menyetujui pemrosesan data untuk pendaftaran</label>\n  <div class=\"invalid-feedback\">Centang untuk melanjutkan.</div>\n</div>\n<div class=\"form-check\">\n  <input class=\"form-check-input\" type=\"checkbox\" id=\"berita\">\n  <label class=\"form-check-label\" for=\"berita\">Kirimi saya info kelas baru (opsional)</label>\n</div>","lang":"html"}]},{"b":["Modal adalah kotak dialog. Strukturnya <code>.modal</code> → <code>.modal-dialog</code> → <code>.modal-content</code> → header, body, footer.","Membukanya cukup dengan tombol berisi <code>data-bs-toggle=\"modal\"</code> dan <code>data-bs-target=\"#idModal\"</code>. Tombol tutup memakai <code>data-bs-dismiss=\"modal\"</code>.","Komponen lain yang memakai pola sama: dropdown (<code>data-bs-toggle=\"dropdown\"</code>), tooltip, offcanvas, accordion, dan toast. Bisa juga dibuka lewat JS: <code>new bootstrap.Modal(el).show()</code>."],"html":"<div class=\"container py-3\">\n  <button class=\"btn btn-danger\" data-bs-toggle=\"modal\" data-bs-target=\"#konfirmasi\">Hapus akun</button>\n</div>\n<div class=\"modal fade\" id=\"konfirmasi\" tabindex=\"-1\" aria-labelledby=\"judulModal\" aria-hidden=\"true\">\n  <div class=\"modal-dialog\">\n    <div class=\"modal-content\">\n      <div class=\"modal-header\"><h5 class=\"modal-title\" id=\"judulModal\">Yakin?</h5>\n        <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Tutup\"></button></div>\n      <div class=\"modal-body\">Akun yang dihapus tidak bisa dipulihkan.</div>\n      <div class=\"modal-footer\">\n        <button class=\"btn btn-danger\">Ya, hapus</button>\n      </div>\n    </div>\n  </div>\n</div>","bs":true,"task":{"q":"Tambahkan tombol \"Batal\" di footer modal yang menutup modal (<code>data-bs-dismiss=\"modal\"</code>).","test":"!!document.querySelector('.modal-footer [data-bs-dismiss=\"modal\"]')","hint":"Tulis <button class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Batal</button> di .modal-footer."},"pts":["data-bs-toggle=\"modal\" + data-bs-target membuka modal.","data-bs-dismiss=\"modal\" menutupnya.","Bisa juga lewat new bootstrap.Modal(el)."],"q":[["Atribut apa untuk tombol yang menutup modal?",["data-bs-dismiss=\"modal\"","data-bs-close","onclick=\"close()\""],0,"data-bs-dismiss menutup komponen induknya."]],"so":[{"q":"Buka modal lewat JavaScript, bukan atribut data, saat halaman selesai dimuat.","h":"new bootstrap.Modal(elemen).show().","a":"<script>\n  const m = new bootstrap.Modal(document.getElementById('konfirmasi'));\n  m.show();\n</script>","lang":"html"},{"q":"Buat modal yang berada di tengah layar dan tidak tertutup saat area luar diklik.","h":"modal-dialog-centered; data-bs-backdrop=\"static\" pada .modal.","a":"<div class=\"modal fade\" id=\"info\" data-bs-backdrop=\"static\" tabindex=\"-1\" aria-hidden=\"true\">\n  <div class=\"modal-dialog modal-dialog-centered\">\n    <div class=\"modal-content\">\n      <div class=\"modal-body\">Pembayaran sedang diproses.</div>\n      <div class=\"modal-footer\"><button class=\"btn btn-primary\" data-bs-dismiss=\"modal\">Mengerti</button></div>\n    </div>\n  </div>\n</div>","lang":"html"}]},{"b":["Bootstrap 5.3 menyimpan warna dan ukuran di <b>variabel CSS</b> berawalan <code>--bs-</code>. Kamu bisa menimpanya: <code>:root { --bs-primary: #B4532A; --bs-primary-rgb: 180,83,42; }</code>. Untuk tombol, ubah variabel komponennya, misalnya <code>.btn-primary { --bs-btn-bg: #B4532A; }</code>.","Untuk kustomisasi menyeluruh, pakai <b>Sass</b>: <code>npm install bootstrap sass</code>, lalu di <code>main.scss</code> tulis <code>$primary: #B4532A;</code> sebelum <code>@import \"bootstrap/scss/bootstrap\";</code>. Semua komponen ikut berubah.","Mode gelap: tambahkan <code>data-bs-theme=\"dark\"</code> pada <code>&lt;html&gt;</code> atau pada satu elemen saja."],"html":"<div class=\"container py-3\">\n  <button id=\"utama\" class=\"btn btn-primary\">Tombol utama</button>\n  <div id=\"kotak\" class=\"card mt-3\"><div class=\"card-body\">Kartu ini bisa dibuat gelap.</div></div>\n</div>","css":".btn-primary {\n  --bs-btn-bg: #B4532A;\n  --bs-btn-border-color: #B4532A;\n  --bs-btn-hover-bg: #8F3F1F;\n}","bs":true,"task":{"q":"Buat kartu tampil gelap dengan menambahkan atribut <code>data-bs-theme=\"dark\"</code> pada <code>#kotak</code>.","test":"document.getElementById('kotak').getAttribute('data-bs-theme')==='dark'","hint":"Tulis data-bs-theme=\"dark\" di tag div#kotak."},"pts":["Variabel --bs-* bisa ditimpa di CSS.","Sass: ubah $primary dll. sebelum import Bootstrap.","data-bs-theme=\"dark\" untuk mode gelap."],"q":[["Cara paling menyeluruh mengganti warna primer Bootstrap?",["Mengubah $primary di Sass sebelum import","Menambah !important di setiap tombol","Mengedit bootstrap.min.css"],0,"Sass membangun ulang semua komponen dengan nilai baru."]],"so":[{"q":"Ubah sudut membulat semua komponen menjadi lebih besar lewat variabel CSS.","h":"Timpa --bs-border-radius (dan variannya) di :root.","a":"<style>\n  :root {\n    --bs-border-radius: .75rem;\n    --bs-border-radius-lg: 1rem;\n    --bs-border-radius-sm: .5rem;\n  }\n</style>","lang":"html"},{"q":"Tulis file Sass yang mengganti warna primer menjadi #B4532A dan font dasar menjadi Inter.","h":"Variabel Sass ditulis sebelum @import bootstrap.","a":"// main.scss\n$primary: #B4532A;\n$font-family-base: \"Inter\", system-ui, sans-serif;\n\n@import \"bootstrap/scss/bootstrap\";","lang":"html"}]},{"b":["Gabungkan navbar, hero, grid kartu yang responsif, dan footer.","Perhatikan grid: <code>row-cols-1 row-cols-md-3</code> adalah cara singkat membuat semua kolom anak sama lebar.","Tantangan: tambahkan kartu kursus keempat dan ubah grid menjadi empat kolom di layar <code>lg</code> dengan <code>row-cols-lg-4</code>."],"html":"<nav class=\"navbar bg-body-tertiary border-bottom\"><div class=\"container\"><span class=\"navbar-brand fw-bold\">RuangKode</span><a class=\"btn btn-sm btn-primary\">Daftar</a></div></nav>\n<header class=\"container py-5 text-center\">\n  <h1 class=\"display-5 fw-bold\">Jadi developer mobile</h1>\n  <p class=\"lead text-body-secondary\">Belajar Dart, Flutter, Kotlin, dan Compose dari nol.</p>\n</header>\n<section class=\"container pb-5\">\n  <div id=\"kursus\" class=\"row row-cols-1 row-cols-md-3 g-3\">\n    <div class=\"col\"><div class=\"card h-100\"><div class=\"card-body\"><h5 class=\"card-title\">Dart</h5><p class=\"card-text\">Bahasa di balik Flutter.</p></div></div></div>\n    <div class=\"col\"><div class=\"card h-100\"><div class=\"card-body\"><h5 class=\"card-title\">Flutter</h5><p class=\"card-text\">Satu kode untuk Android dan iOS.</p></div></div></div>\n    <div class=\"col\"><div class=\"card h-100\"><div class=\"card-body\"><h5 class=\"card-title\">Kotlin</h5><p class=\"card-text\">Bahasa resmi Android.</p></div></div></div>\n  </div>\n</section>\n<footer class=\"border-top py-3 text-center small text-body-secondary\">© 2026 RuangKode</footer>","bs":true,"task":{"q":"Tambahkan kartu keempat di <code>#kursus</code> dan kelas <code>row-cols-lg-4</code>.","test":"(g=>g.children.length>=4&&g.classList.contains('row-cols-lg-4'))(document.getElementById('kursus'))","hint":"Salin satu div.col, ubah judulnya, lalu tambahkan row-cols-lg-4 pada div#kursus."},"pts":["row-cols-* menyamakan lebar semua kolom anak.","card h-100 membuat tinggi kartu seragam."],"q":[["Tailwind dan Bootstrap, mana yang menyediakan komponen siap pakai seperti modal?",["Bootstrap","Tailwind","Keduanya sama persis"],0,"Tailwind fokus pada utilitas; Bootstrap menyertakan komponen dan JS-nya."]],"so":[{"q":"Tambahkan bagian FAQ memakai accordion Bootstrap dengan dua pertanyaan.","h":"accordion > accordion-item > accordion-header (button) + accordion-collapse.","a":"<div class=\"accordion container mb-5\" id=\"faq\">\n  <div class=\"accordion-item\">\n    <h2 class=\"accordion-header\"><button class=\"accordion-button\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#q1\">Apakah gratis?</button></h2>\n    <div id=\"q1\" class=\"accordion-collapse collapse show\" data-bs-parent=\"#faq\"><div class=\"accordion-body\">Ya, semua materi gratis.</div></div>\n  </div>\n  <div class=\"accordion-item\">\n    <h2 class=\"accordion-header\"><button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#q2\">Perlu instal sesuatu?</button></h2>\n    <div id=\"q2\" class=\"accordion-collapse collapse\" data-bs-parent=\"#faq\"><div class=\"accordion-body\">Cukup browser untuk sebagian besar latihan.</div></div>\n  </div>\n</div>","lang":"html"}]},{"b":["<b>Dropdown</b>: tombol dengan <code>data-bs-toggle=\"dropdown\"</code> dan daftar <code>.dropdown-menu</code> berisi <code>.dropdown-item</code>.","<b>Tab</b>: <code>.nav.nav-tabs</code> berisi tombol <code>data-bs-toggle=\"tab\"</code> yang menunjuk ke <code>.tab-pane</code> di dalam <code>.tab-content</code>.","<b>Accordion</b>: daftar bagian yang bisa dilipat. Tambahkan <code>data-bs-parent</code> agar hanya satu bagian terbuka dalam satu waktu. Semua ini berjalan tanpa JavaScript tambahan."],"html":"<div class=\"container py-3\">\n  <div class=\"dropdown mb-3\">\n    <button class=\"btn btn-secondary dropdown-toggle\" data-bs-toggle=\"dropdown\" aria-expanded=\"false\">Urutkan</button>\n    <ul class=\"dropdown-menu\">\n      <li><a class=\"dropdown-item\" href=\"#\">Termurah</a></li>\n      <li><a class=\"dropdown-item\" href=\"#\">Terbaru</a></li>\n    </ul>\n  </div>\n  <ul class=\"nav nav-tabs\" role=\"tablist\">\n    <li class=\"nav-item\"><button class=\"nav-link active\" data-bs-toggle=\"tab\" data-bs-target=\"#deskripsi\" type=\"button\" role=\"tab\">Deskripsi</button></li>\n    <li class=\"nav-item\"><button class=\"nav-link\" data-bs-toggle=\"tab\" data-bs-target=\"#ulasan\" type=\"button\" role=\"tab\">Ulasan</button></li>\n  </ul>\n  <div id=\"isiTab\" class=\"tab-content border border-top-0 p-3\">\n    <div class=\"tab-pane fade show active\" id=\"deskripsi\" role=\"tabpanel\">Kopi arabika 250 gram.</div>\n    <div class=\"tab-pane fade\" id=\"ulasan\" role=\"tabpanel\">★★★★★ Enak sekali.</div>\n  </div>\n</div>","bs":true,"task":{"q":"Tambahkan tab ketiga \"Pengiriman\" lengkap dengan tab-pane berisi teksnya.","test":"document.querySelectorAll('.nav-tabs .nav-link').length>=3&&document.querySelectorAll('#isiTab .tab-pane').length>=3","hint":"Salin satu li.nav-item dan satu div.tab-pane, beri id baru, dan samakan data-bs-target dengan id itu."},"pts":["dropdown: data-bs-toggle=\"dropdown\".","tab: data-bs-toggle=\"tab\" + tab-pane.","accordion: data-bs-parent agar satu terbuka."],"q":[["Atribut accordion agar hanya satu bagian terbuka?",["data-bs-parent","data-single","aria-expanded"],0,"Menunjuk ke wadah accordion."]]},{"b":["<b>Offcanvas</b> adalah panel yang meluncur dari tepi layar, cocok untuk menu samping atau filter di ponsel. Dibuka dengan <code>data-bs-toggle=\"offcanvas\"</code>.","<b>Toast</b> adalah notifikasi kecil yang muncul lalu hilang. Toast dan <b>tooltip</b> perlu diaktifkan dengan JavaScript: <code>new bootstrap.Toast(el).show()</code> dan <code>new bootstrap.Tooltip(el)</code>.","Komponen yang perlu diaktifkan lewat JS ini disebut opt-in, karena demi performa Bootstrap tidak memasangnya otomatis."],"html":"<div class=\"container py-3 d-flex gap-2 flex-wrap\">\n  <button class=\"btn btn-outline-dark\" data-bs-toggle=\"offcanvas\" data-bs-target=\"#filter\">Filter</button>\n  <button id=\"btnToast\" class=\"btn btn-success\">Tambah ke keranjang</button>\n  <button id=\"info\" class=\"btn btn-outline-secondary\" data-bs-toggle=\"tooltip\" data-bs-title=\"Gratis ongkir di atas Rp100.000\">Info ongkir</button>\n</div>\n<div class=\"offcanvas offcanvas-start\" tabindex=\"-1\" id=\"filter\">\n  <div class=\"offcanvas-header\"><h5 class=\"offcanvas-title\">Filter</h5><button class=\"btn-close\" data-bs-dismiss=\"offcanvas\" aria-label=\"Tutup\"></button></div>\n  <div class=\"offcanvas-body\">Harga, kategori, rating...</div>\n</div>\n<div class=\"toast-container position-fixed bottom-0 end-0 p-3\">\n  <div id=\"notif\" class=\"toast\" role=\"status\" aria-live=\"polite\">\n    <div class=\"toast-body\">Produk ditambahkan ke keranjang.</div>\n  </div>\n</div>","js":"document.getElementById('btnToast').addEventListener('click', () => {\n  new bootstrap.Toast(document.getElementById('notif')).show();\n});\n// aktifkan tooltip di sini","bs":true,"task":{"q":"Aktifkan tooltip pada tombol <code>#info</code> dengan <code>new bootstrap.Tooltip(...)</code>, lalu tekan Jalankan dan Periksa.","test":"!!(window.bootstrap&&bootstrap.Tooltip.getInstance(document.getElementById('info')))","hint":"new bootstrap.Tooltip(document.getElementById('info'));"},"pts":["offcanvas untuk panel samping.","Toast dan tooltip diaktifkan dengan JS.","toast-container position-fixed untuk posisi."],"q":[["Komponen mana yang harus diaktifkan lewat JavaScript?",["Tooltip","Card","Grid"],0,"Tooltip dan popover bersifat opt-in."]]},{"b":["Tabel: <code>.table</code> lalu tambahan <code>.table-striped</code> (belang), <code>.table-hover</code>, <code>.table-sm</code>. Bungkus dengan <code>.table-responsive</code> agar tabel lebar bisa digulir di ponsel tanpa merusak halaman.","<b>List group</b> (<code>.list-group</code> dan <code>.list-group-item</code>) cocok untuk daftar pengaturan atau riwayat, dan bisa dipadukan dengan badge.","<b>Pagination</b> (<code>.pagination</code>, <code>.page-item</code>, <code>.page-link</code>) untuk berpindah halaman data. Tandai halaman aktif dengan <code>.active</code> dan <code>aria-current=\"page\"</code>."],"html":"<div class=\"container py-3\">\n  <div class=\"table-responsive\">\n    <table id=\"tabel\" class=\"table\">\n      <thead><tr><th>Produk</th><th class=\"text-end\">Harga</th><th class=\"text-end\">Stok</th></tr></thead>\n      <tbody>\n        <tr><td>Kopi Gayo</td><td class=\"text-end\">85.000</td><td class=\"text-end\">12</td></tr>\n        <tr><td>Kopi Toraja</td><td class=\"text-end\">90.000</td><td class=\"text-end\">4</td></tr>\n        <tr><td>Kopi Kintamani</td><td class=\"text-end\">80.000</td><td class=\"text-end\">0</td></tr>\n      </tbody>\n    </table>\n  </div>\n  <nav aria-label=\"Halaman produk\">\n    <ul class=\"pagination\">\n      <li class=\"page-item\"><a class=\"page-link\" href=\"#\">1</a></li>\n      <li class=\"page-item\"><a class=\"page-link\" href=\"#\">2</a></li>\n      <li class=\"page-item\"><a class=\"page-link\" href=\"#\">3</a></li>\n    </ul>\n  </nav>\n</div>","bs":true,"task":{"q":"Beri tabel kelas <code>table-striped</code> dan <code>table-hover</code>, lalu tandai halaman 1 sebagai aktif (<code>active</code> pada li pertama).","test":"(t=>t.classList.contains('table-striped')&&t.classList.contains('table-hover'))(document.getElementById('tabel'))&&document.querySelector('.pagination .page-item').classList.contains('active')","hint":"Tambahkan dua kelas pada table#tabel dan active pada li.page-item pertama."},"pts":["table + table-striped/hover, bungkus table-responsive.","list-group untuk daftar.","pagination dengan active dan aria-current."],"q":[["Kenapa tabel dibungkus .table-responsive?",["Agar bisa digulir horizontal di layar sempit","Agar berwarna","Agar bisa diurutkan"],0,"Halaman tidak ikut melebar."]]},{"b":["<code>.hstack</code> dan <code>.vstack</code> adalah jalan pintas flexbox dengan <code>gap-*</code>. <code>.ms-auto</code> mendorong elemen ke kanan.","Posisi: <code>position-relative</code>, <code>position-absolute</code>, <code>top-0 start-100 translate-middle</code> untuk badge notifikasi di pojok tombol.","Rasio: <code>.ratio .ratio-16x9</code> menjaga video atau gambar tetap proporsional. <code>object-fit-cover</code> memotong gambar agar penuh tanpa gepeng."],"html":"<div class=\"container py-3\">\n  <div class=\"hstack gap-3 p-3 border rounded\">\n    <b>Keranjang</b>\n    <button id=\"lonceng\" class=\"btn btn-primary ms-auto\">\n      Notifikasi\n    </button>\n  </div>\n  <div class=\"ratio ratio-16x9 mt-3 bg-secondary-subtle rounded\"><div class=\"d-flex align-items-center justify-content-center\">Area video 16:9</div></div>\n</div>","bs":true,"task":{"q":"Tambahkan badge merah angka 3 di pojok kanan atas tombol: tombol diberi <code>position-relative</code>, badge diberi <code>position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger</code>.","test":"(b=>b.classList.contains('position-relative')&&!!b.querySelector('.badge.position-absolute.bg-danger'))(document.getElementById('lonceng'))","hint":"<span class=\"position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger\">3</span> di dalam tombol."},"pts":["hstack/vstack + gap.","position-* + translate-middle untuk badge pojok.","ratio-16x9 untuk proporsi tetap."],"q":[["Kelas yang mendorong elemen ke kanan di dalam flex?",["ms-auto","float-end","text-end"],0,"margin-start auto memakan ruang kosong."]]}]);
